content:
:root { --accent: #2b6cb0; --accent-dark: #1f4e86; --accent-soft: #eaf2fb; --accent-line: #c9dcf0;
  --btn: #2b6cb0; --btn-dark: #1f4e86;
  --new: #6f42c1; --warn: #8a5a00; --warn-bg: #fff4d6; --warn-line: #f0d58a; --danger: #c0392b;
  --danger-text: #b02a37; --danger-bg: #fff7f6; --amber-text: #b45309;
  --text: #1f2933; --muted: #4b535a; --faint: #6b737a; --line: #dfe4ea; --line-strong: #ccd3da;
  --page: #f5f7fa; --page-rgb: 245,247,250; --surface: #ffffff; --surface-2: #f5f7fa; --surface-3: #eceff2; --hover: #f0f4f8;
  --shimmer-a: #eef1f5; --shimmer-b: #f8fafc; }
/* Dark theme: the same variables, set when the page carries data-theme="dark" (see the toggle in the header) */
html[data-theme="dark"] { color-scheme: dark;
  --accent: #5ba0e6; --accent-dark: #8dbcf0; --accent-soft: #1b2b3d; --accent-line: #2a4561;
  --btn: #2b6cb0; --btn-dark: #3a7bc4;
  --new: #a98bf0; --warn: #e6b15c; --warn-bg: #2f2612; --warn-line: #5c4a1f; --danger: #e5604f;
  --danger-text: #f08a7d; --danger-bg: #2a1715; --amber-text: #f0a35a;
  --text: #e4e8ec; --muted: #a4afba; --faint: #8a95a1; --line: #2b343e; --line-strong: #3a4551;
  --page: #0f1419; --page-rgb: 15,20,25; --surface: #171d24; --surface-2: #1d252e; --surface-3: #26303b; --hover: #222c37;
  --shimmer-a: #1d252e; --shimmer-b: #26303b; }
body { background: var(--page); color: var(--text); font-size: 14.5px; }
h4 { font-weight: 600; }
h1, h2, h3, h4 { letter-spacing: -0.01em; }
.well { background: var(--surface); border: 1px solid var(--line); box-shadow: 0 1px 2px rgba(16,24,40,0.04); }
.btn-primary { background: var(--btn); border-color: var(--btn-dark); }
.btn-primary:hover, .btn-primary:focus, .btn-primary:active, .btn-primary.active { background: var(--btn-dark); border-color: var(--btn-dark); }
.nav-tabs > li.active > a, .nav-tabs > li.active > a:hover, .nav-tabs > li.active > a:focus { color: var(--accent-dark); background: var(--page); border-color: var(--line) var(--line) var(--page); font-weight: 600; }
.nav-tabs > li > a { color: var(--muted); }
.nav-tabs > li > a:hover { background: var(--accent-soft); border-color: var(--line); }
a { color: var(--accent); } a:hover { color: var(--accent-dark); }
.selectize-input.focus, .form-control:focus { border-color: var(--accent); box-shadow: 0 0 0 2px var(--accent-line); }
/* Results tabs look muted until there is something to read in them */
body:not(.has-results) #tabs > li > a[data-value='Forecast'],
body:not(.has-results) #tabs > li > a[data-value='Sensitivity'],
body:not(.has-results) #tabs > li > a[data-value='Assumption draws'],
body:not(.has-results) #tabs > li > a[data-value='Survival curves'] { color: var(--faint); }
.empty-state { text-align: center; padding: 34px 20px; margin: 10px 0 14px; border: 1px dashed var(--line-strong);
  border-radius: 8px; background: var(--surface); }
.empty-title { font-size: 16px; font-weight: 600; margin-bottom: 4px; }
.empty-text { color: var(--muted); margin: 0 auto 14px; max-width: 460px; }
body.has-results .empty-state { display: none; }
body:not(.has-results) .results-body { display: none; }
.run-dock { position: sticky; bottom: 0; z-index: 5; background: var(--surface); margin: 0 -14px -12px; padding: 10px 14px 12px;
  border-top: 1px solid var(--line); }
#run { font-weight: 600; letter-spacing: 0.01em; box-shadow: 0 1px 2px rgba(16,24,40,0.2); }
.sec-count { margin-left: 8px; font-size: 12px; font-weight: 400; color: var(--muted); }
.sec-desc { font-size: 12.5px; color: var(--muted); margin: -4px 0 8px; }
.card-legend { font-size: 12px; color: var(--muted); display: grid; grid-template-rows: 0fr; opacity: 0;
  transition: grid-template-rows .3s ease, opacity .25s ease; }
.card-legend-in { overflow: hidden; min-height: 0; display: flex; flex-wrap: wrap; gap: 4px 14px; padding-bottom: 0;
  transition: padding-bottom .3s ease; }
.card-legend.on .card-legend-in { padding-bottom: 10px; }
.card-legend span::before { content: ''; display: inline-block; width: 3px; height: 11px; margin-right: 5px;
  vertical-align: -1px; border-radius: 2px; background: #c3cad1; }
.card-legend .lg-edit::before { background: var(--btn); }
.card-legend .lg-run::before { background: #e0a800; }
.card-legend .lg-up::before { background: var(--new); }
.assump-card { transition: box-shadow .15s ease, border-color .15s ease, background-color .15s ease; }
.assump-card:not(.card-off):hover { box-shadow: 0 2px 8px rgba(16,24,40,0.12); border-color: var(--accent-line); background: var(--surface-2); }

@media (max-width: 767px) { html { overflow-y: scroll; } }
.container-fluid { padding-top: 14px; }
.container-fluid > h2 { margin: 8px 0 28px; }
.app-brand { display: flex; align-items: center; gap: 14px; }
.app-logo { height: 38px; width: auto; display: block; }
.app-mosquito { height: 36px; width: auto; display: block; margin-left: -14px; }
.app-brand-text { font-size: 22px; font-weight: 400; color: var(--muted); line-height: 1.2; }
@media (max-width: 500px) { .app-brand-text { font-size: 16px; } .app-logo { height: 30px; } .app-mosquito { height: 28px; } }
body { padding-bottom: 36px; }
.app-footer { position: fixed; left: 0; bottom: 0; z-index: 1000; padding: 4px 14px;
  font-size: 12px; color: var(--muted); background: rgba(var(--page-rgb), 0.92);
  border-top-right-radius: 6px; }
.well { padding: 12px 14px; }
.well a:not(.btn) { color: var(--accent-dark); }
.well .form-group { margin-bottom: 8px; }
.well label.control-label { margin-bottom: 2px; font-size: 13px; }
.well .form-control { height: 30px; padding: 3px 8px; font-size: 13px; }
.well .selectize-input { min-height: 30px; padding: 4px 8px; }
#n_iter + .selectize-control.single .selectize-input { padding-right: 22px; font-size: 12px; white-space: nowrap; }
.well .row > [class*='col-'] { padding-left: 5px; padding-right: 5px; }
.well .row { margin-left: -5px; margin-right: -5px; }
#shiny-notification-panel { position: static; width: 100%; margin-top: 10px; }
#shiny-notification-panel .shiny-notification { position: relative; width: 100%;
  margin: 0 0 8px; right: auto; z-index: 1100; }
#tabs > li > a[data-value='Forecast']::before,
#tabs > li > a[data-value='Sensitivity']::before,
#tabs > li > a[data-value='Assumption draws']::before,
#tabs > li > a[data-value='Survival curves']::before {
  content: ''; display: inline-block; box-sizing: border-box; width: 7px; height: 7px;
  margin: 0 8.5px 0 1.5px; border-radius: 50%; border: 1.5px solid var(--line-strong); background: transparent;
  vertical-align: middle; position: relative; top: -1px;
  transition: background-color .3s, border-color .3s, box-shadow .3s; }
/* Three pulses, each a ring that expands and fades while the steady glow stays put, so after
   the third pulse the dot simply stays lit with no jump. */
#tabs > li > a.tab-new::before { background: var(--new); border-color: var(--new);
  box-shadow: 0 0 0 0 rgba(111,66,193,0), 0 0 6px 2px rgba(111,66,193,0.5);
  animation: dot-pulse 1.2s ease-out 3; }
@keyframes dot-pulse {
  0%   { box-shadow: 0 0 0 0 rgba(111,66,193,0.6), 0 0 6px 2px rgba(111,66,193,0.5); }
  75%  { box-shadow: 0 0 0 10px rgba(111,66,193,0), 0 0 6px 2px rgba(111,66,193,0.5); }
  100% { box-shadow: 0 0 0 10px rgba(111,66,193,0), 0 0 6px 2px rgba(111,66,193,0.5); } }
.assump-desc { font-size: 12px; line-height: 1.3; color: var(--muted); margin: 2px 0 8px; }
.tab-content > .tab-pane.fade { transition: opacity .2s ease; }
@keyframes fade-in { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: none; } }
.recalculating { opacity: 0.55 !important; }
.shiny-image-output, .shiny-html-output, .shiny-bound-output img { transition: opacity .35s ease; }
.stale-note { animation: slide-in .25s ease-out; }
@keyframes slide-in { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: none; } }
#preset .radio label span, .btn { transition: background-color .15s, border-color .15s, color .15s; }
#run.running { cursor: progress; animation: run-pulse 1.1s ease-in-out infinite; }
@keyframes run-pulse { 0%, 100% { opacity: 0.95; } 50% { opacity: 0.6; } }
#run { transition: background-color .3s ease, border-color .3s ease, box-shadow .3s ease; }
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation: none !important; transition: none !important; } }
.stale-note { font-size: 12px; color: var(--warn); background: var(--warn-bg); border: 1px solid var(--warn-line);
  border-radius: 4px; padding: 5px 8px; margin-top: 8px; }
.preset-reset { font-size: 12px; margin: 0 0 8px; }
.assump-invalid { border-color: #dc3545 !important; box-shadow: 0 0 0 1px #dc3545; }
.assump-err { color: var(--danger-text); font-size: 12px; margin-top: 4px; }
.assump-err:empty { display: none; }
.check-result { font-size: 13px; color: var(--muted); margin-top: 8px; }
input:-moz-ui-invalid { box-shadow: none; }
input:disabled, .form-control:disabled { background: var(--surface-2); color: var(--faint); cursor: not-allowed; }
/* Fixed frame on larger screens: title, settings and tab bar stay put; only tab content scrolls */
@media (min-width: 768px) {
  html, body { height: 100%; overflow: hidden; }
  body { padding-bottom: 0; }
  .container-fluid { height: 100vh; display: flex; flex-direction: column; padding-bottom: 34px; }
  .container-fluid > h2 { flex: none; margin: 6px 0 18px; }
  .container-fluid > .row { flex: 1 1 auto; min-height: 0; display: flex; }
  .container-fluid > .row::before, .container-fluid > .row::after { content: none; }
  .container-fluid > .row > .col-sm-3 { overflow-y: auto; max-height: 100%; padding-bottom: 8px; }
  .container-fluid > .row > .col-sm-9 { display: flex; flex-direction: column; min-height: 0; }
  .container-fluid > .row > .col-sm-9 > .tabbable { display: flex; flex-direction: column; flex: 1 1 auto; min-height: 0; }
  .tabbable > .nav-tabs { flex: none; }
  .tabbable > .tab-content { flex: 1 1 auto; min-height: 0; overflow-y: scroll; overflow-x: hidden;
    padding: 0 6px 0 0; }
  /* Spacer at rest; once you scroll it sticks under the tabs and blurs what slides beneath */
  .tabbable > .tab-content::before { content: ''; display: block; position: sticky; top: 0; z-index: 20;
    height: 22px; pointer-events: none;
    background: linear-gradient(to bottom, rgba(var(--page-rgb), 0.92), rgba(var(--page-rgb), 0));
    -webkit-backdrop-filter: blur(7px); backdrop-filter: blur(7px);
    -webkit-mask-image: linear-gradient(to bottom, #000 55%, transparent);
    mask-image: linear-gradient(to bottom, #000 55%, transparent); }
  /* Pull the jump bar up over the spacer so its top gap matches the gap under the chips */
  .jump-bar { margin-top: -22px; }
  /* Slide-out settings panel: the column keeps its width and slides off to the left */
  .container-fluid > .row > .col-sm-3 { transition: margin-left .35s ease, opacity .3s ease, visibility 0s linear 0s; }
  .container-fluid > .row > .col-sm-9 { transition: width .35s ease, margin-left .35s ease; }
  .sidebar-collapsed > .row > .col-sm-3 { margin-left: -25%; opacity: 0; visibility: hidden;
    pointer-events: none; transition: margin-left .35s ease, opacity .25s ease, visibility 0s linear .35s; }
  .sidebar-collapsed > .row > .col-sm-9 { width: calc(100% - 30px); margin-left: 30px; }
  .sidebar-collapsed .sidebar-arrow-open { opacity: 1; visibility: visible; transition: opacity .3s ease .25s, visibility 0s; }
}
.howto { position: relative; background: var(--surface-2); border: 1px solid var(--line); border-radius: 6px;
  padding: 11px 14px 12px; font-size: 13px; margin-bottom: 14px; }
.howto-title { font-weight: 700; font-size: 14px; margin-bottom: 8px; }
.howto-steps { display: grid; grid-template-columns: repeat(auto-fit, minmax(210px, 1fr)); gap: 10px; }
.howto-step { display: flex; gap: 10px; align-items: flex-start; background: var(--surface);
  border: 1px solid var(--line); border-radius: 6px; padding: 9px 11px; }
.howto-num { flex: none; width: 24px; height: 24px; border-radius: 50%; background: var(--btn-dark); color: #fff;
  font-weight: 700; font-size: 13px; line-height: 24px; text-align: center; }
.howto-step-title { font-weight: 700; font-size: 13px; margin-bottom: 1px; }
.howto-step-text { font-size: 12.5px; line-height: 1.4; color: var(--text); }
.howto-step-text kbd { font-size: 11px; padding: 0 5px; color: var(--text); background: var(--surface-2);
  border: 1px solid var(--line-strong); border-radius: 3px; box-shadow: none; white-space: nowrap; }
.howto-note { margin-top: 9px; font-size: 12px; color: var(--muted); display: flex; align-items: center; gap: 7px; }
.legend-dot { flex: none; width: 7px; height: 7px; border-radius: 50%; background: var(--new);
  box-shadow: 0 0 5px 1px rgba(111,66,193,0.5); }
.howto-close { position: absolute; top: 3px; right: 8px; border: 0; background: none;
  font-size: 20px; line-height: 1; color: var(--muted); cursor: pointer; }
.tab-content { padding-top: 16px; }
@media (min-width: 768px) { .tab-content { padding-top: 0; } }
#rand_seed { font-size: 14px; margin-left: 5px; text-decoration: none; }
.settings-io { display: flex; flex-wrap: wrap; gap: 8px; align-items: flex-start; justify-content: flex-start; margin: 0 0 10px; }
.settings-io .form-group { margin: 0; height: 30px; width: auto; }
.settings-io .input-group { display: block; }
.settings-io .input-group .form-control { display: none; }
.settings-io .input-group-btn { display: block; width: auto; }
.settings-io .btn-file, .settings-io .btn { border-radius: 3px; font-size: 12px; padding: 0 12px; height: 30px;
  line-height: 28px; margin: 0; display: inline-block; box-sizing: border-box; }
.settings-io .progress { display: none; }
.dist-help { font-size: 12px; line-height: 1.3; color: var(--muted); margin: -2px 0 8px; }
.assump-card.card-off { position: relative; }
.assump-card.card-off > * { opacity: 0.5; filter: grayscale(1); }
.assump-card.card-off::after { content: ''; position: absolute; top: 0; right: 0; bottom: 0; left: 0;
  cursor: not-allowed; z-index: 5; }
.assump-card.card-off::before { content: attr(data-tip); position: absolute; left: 50%; top: 50%; z-index: 10;
  transform: translate(-50%, -50%); width: 86%; padding: 6px 10px; border-radius: 4px; text-align: center;
  font-size: 12px; line-height: 1.3; color: #fff; background: rgba(33, 37, 41, 0.92); pointer-events: none;
  opacity: 0; transition: opacity .15s ease; }
.assump-card.card-off:hover::before { opacity: 1; }
@media (prefers-reduced-motion: reduce) { .assump-card.card-off::before { transition: none; } }
.fit-help { margin: 4px 0 8px; font-size: 12px; }
.fit-help summary { cursor: pointer; color: var(--accent-dark); margin-bottom: 4px; }
.fit-help .fit-note, .fit-msg { font-size: 12px; line-height: 1.3; color: var(--muted); margin-bottom: 6px; }
.fit-msg.bad { color: var(--danger-text); }
.assump-note { font-size: 12px; line-height: 1.3; color: var(--warn); background: var(--warn-bg); border: 1px solid var(--warn-line);
  border-radius: 4px; padding: 4px 6px; margin: 0 0 8px; }
.link-box { background: var(--surface-2); border: 1px solid var(--line); border-radius: 6px; padding: 10px 14px 12px; margin-bottom: 14px; }
.corr-add { margin-top: 25px; }
.corr-row { font-size: 13px; padding: 3px 0; border-bottom: 1px solid var(--line); }
.corr-row a { margin-left: 10px; font-size: 12px; }
.corr-row.inactive { color: var(--muted); }
.assump-upload { color: var(--accent-dark); font-size: 12px; margin-top: 4px; }
.assump-upload:empty { display: none; }
.assump-card.assump-uploaded { border-left: 3px solid var(--new); }
.assump-card.assump-differs { border-left: 3px solid var(--accent); }
.jump-bar { position: sticky; top: 0; z-index: 25; background: var(--page); display: flex; flex-wrap: wrap;
  align-items: center; gap: 6px; padding: 8px 0; margin-bottom: 10px; border-bottom: 1px solid var(--line); }
.jump-chip { border: 1px solid var(--line-strong); background: var(--surface); color: var(--text); border-radius: 14px; padding: 2px 11px;
  font-size: 12.5px; cursor: pointer; transition: background-color .15s, color .15s, border-color .15s; }
.jump-chip:hover { background: var(--hover); }
.jump-chip { position: relative; }
.jump-chip[data-tip]::after { content: attr(data-tip); position: absolute; left: 0; top: calc(100% + 8px); z-index: 40;
  width: 250px; padding: 6px 10px; border-radius: 4px; text-align: left; white-space: normal;
  font-size: 12px; line-height: 1.35; color: #fff; background: rgba(33, 37, 41, 0.94); pointer-events: none;
  opacity: 0; visibility: hidden; transition: opacity .15s ease .3s, visibility 0s linear .45s; }
.jump-chip[data-tip]:hover::after, .jump-chip[data-tip]:focus-visible::after { opacity: 1; visibility: visible;
  transition: opacity .15s ease .3s, visibility 0s linear .3s; }
@media (prefers-reduced-motion: reduce) { .jump-chip[data-tip]::after { transition: none; } }
.jump-chip.active { background: var(--btn); border-color: var(--accent-dark); color: #fff; }
.jump-count { margin-left: 6px; font-size: 11px; opacity: 0.85; }
.jump-count:empty { display: none; }
.jump-actions { margin-left: auto; font-size: 12px; color: var(--muted); }
.jump-sep { margin: 0 6px; color: var(--faint); }
.link-btn { border: 0; background: none; padding: 0; color: var(--accent-dark); cursor: pointer; font-size: inherit; }
.link-btn:hover { text-decoration: underline; }
.howto-open { display: none; font-size: 12.5px; margin: 0 0 8px; }
.assump-section { scroll-margin-top: 54px; margin-bottom: 16px; }
.cards-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(215px, 1fr)); gap: 12px; align-items: start; }
.assump-card { margin: 0; cursor: pointer; }
.assump-body { cursor: default; }
.assump-toggle { display: flex; gap: 6px; align-items: flex-start; flex: 1; border: 0; background: none; padding: 0;
  text-align: left; cursor: pointer; font-size: 14px; color: inherit; }
.chev { flex: none; font-size: 10px; margin-top: 5px; color: var(--muted); transition: transform .25s ease; }
.assump-card.open .chev, .adv-open .chev { transform: rotate(90deg); }
.assump-summary { font-size: 12px; color: var(--muted); margin: 3px 0 2px 16px; line-height: 1.3; }
/* Open and close: the row height animates between 0 and its natural height, the content fades,
   and a closed body is hidden from the keyboard and screen readers once it has finished closing */
.assump-body, .adv-body { display: grid; grid-template-rows: 0fr; visibility: hidden;
  transition: grid-template-rows .38s cubic-bezier(.4,0,.2,1), visibility 0s linear .38s; }
.assump-card.open .assump-body, .adv-open .adv-body { grid-template-rows: 1fr; visibility: visible;
  transition: grid-template-rows .38s cubic-bezier(.4,0,.2,1), visibility 0s; }
.assump-body-clip, .adv-clip { overflow: hidden; min-height: 0; }
.assump-body-pad { margin-top: 8px; padding-top: 8px; border-top: 1px solid var(--line); opacity: 0;
  transition: opacity .15s ease; }
.assump-card.open .assump-body-pad { opacity: 1; transition: opacity .3s ease .12s; }
.adv-clip > .link-box { margin-top: 8px; opacity: 0; transition: opacity .15s ease; }
.adv-open .adv-clip > .link-box { opacity: 1; transition: opacity .25s ease .1s; }
.fold { margin: 6px 0 14px; }
.fold .adv-toggle strong { font-size: 18px; font-weight: 500; }
.adv-clip > .eq-pad { margin-top: 8px; opacity: 0; transition: opacity .15s ease; }
.adv-open .adv-clip > .eq-pad { opacity: 1; transition: opacity .25s ease .1s; }
.adv-toggle { display: flex; gap: 6px; align-items: center; border: 0; background: none; padding: 4px 0;
  cursor: pointer; font-size: 16px; text-align: left; }
.adv-tag { font-size: 11px; color: var(--muted); border: 1px solid var(--line-strong); border-radius: 9px; padding: 0 7px; }
.adv-status { font-size: 12.5px; color: var(--muted); margin-left: 4px; }
.draws-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 10px; }
.draw-tile { cursor: zoom-in; border: 1px solid var(--line); border-radius: 6px; padding: 4px; background: var(--surface);
  transition: box-shadow .15s, border-color .15s; }
.draw-tile:hover, .draw-tile:focus-visible { box-shadow: 0 2px 8px rgba(0,0,0,0.15); border-color: var(--accent); }
.assump-warn { color: var(--warn); font-size: 12px; margin-top: 4px; }
.assump-warn:empty { display: none; }
a:focus-visible, button:focus-visible, .btn:focus-visible, input:focus-visible,
select:focus-visible, .selectize-input.focus, .nav-tabs > li > a:focus-visible {
  outline: 2px solid var(--accent); outline-offset: 2px; }
.btn-file:focus-within { outline: 2px solid var(--accent); outline-offset: 2px; }
.assump-prev { margin-top: 4px; }
.container-fluid { position: relative; }
.settings-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; }
.well { position: relative; }
.sidebar-arrow, .sidebar-arrow-open { border: 1px solid var(--line-strong); background: var(--surface); color: var(--muted); border-radius: 50%;
  width: 24px; height: 24px; padding: 0; font-size: 11px; line-height: 22px; text-align: center; cursor: pointer;
  transition: background-color .15s, color .15s, border-color .15s; }
.sidebar-arrow:hover, .sidebar-arrow-open:hover { background: var(--btn); border-color: var(--accent-dark); color: #fff; }
.sidebar-arrow-open { position: absolute; left: 15px; top: 76px; z-index: 30; opacity: 0; visibility: hidden;
  transition: opacity .15s ease, visibility 0s linear .15s; }
@media (max-width: 767px) { .sidebar-arrow, .sidebar-arrow-open { display: none; } }
